CREATE OR REPLACE FUNCTION public.erp_inventory_pool_company(p_selling_company_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_seller public.companies%rowtype;
  v_pool public.companies%rowtype;
  v_source_key text;
begin
  select * into v_seller from public.companies company
  where company.id = p_selling_company_id and coalesce(company.is_active, true);
  if not found then raise exception using errcode='P0002', message='INVENTORY_POOL_SELLING_COMPANY_INVALID'; end if;
  if coalesce((v_seller.metadata ->> 'inventory_owner')::boolean, false) then return v_seller.id; end if;
  v_source_key := nullif(btrim(v_seller.metadata ->> 'availability_source_company_key'), '');
  if v_source_key is null then raise exception using errcode='23514', message='INVENTORY_POOL_MAPPING_REQUIRED'; end if;
  select * into v_pool from public.companies company
  where company.company_key = v_source_key and coalesce(company.is_active, true);
  if not found or not coalesce((v_pool.metadata ->> 'inventory_owner')::boolean, false) then
    raise exception using errcode='23514', message='INVENTORY_POOL_MAPPING_INVALID';
  end if;
  if v_pool.id = v_seller.id then raise exception using errcode='23514', message='INVENTORY_POOL_MAPPING_CYCLIC'; end if;
  return v_pool.id;
end;
$function$
